#include "ui/tabs/booking/OnlineBookingPage.h"
#include "core/crm/OnlineBookingService.h"
#include <QAbstractItemView>
#include <QHeaderView>
#include <QInputDialog>
#include <QLineEdit>
#include <QMessageBox>
#include <QPushButton>
#include <QTableWidget>
#include <QTableWidgetItem>
#include <QVBoxLayout>
#include <QHBoxLayout>

OnlineBookingPage::OnlineBookingPage(QWidget* parent):QWidget(parent){ buildUi(); refresh(); }
void OnlineBookingPage::buildUi(){ auto* l=new QVBoxLayout(this); auto* row=new QHBoxLayout(); for(auto pair: {qMakePair(QString::fromUtf8("Підтвердити"),QStringLiteral("confirmed")),qMakePair(QString::fromUtf8("Відхилити"),QStringLiteral("cancelled")),qMakePair(QString::fromUtf8("Не з’явився"),QStringLiteral("no_show"))}){ auto* b=new QPushButton(pair.first,this); connect(b,&QPushButton::clicked,this,[this,pair](){ updateSelectedStatus(pair.second);}); row->addWidget(b);} auto* move=new QPushButton(QString::fromUtf8("Перенести"),this); connect(move,&QPushButton::clicked,this,&OnlineBookingPage::rescheduleSelected); row->addWidget(move); auto* create=new QPushButton(QString::fromUtf8("Створити наряд"),this); connect(create,&QPushButton::clicked,this,&OnlineBookingPage::createOrderFromSelected); row->addWidget(create); auto* msg=new QPushButton(QString::fromUtf8("Написати клієнту"),this); connect(msg,&QPushButton::clicked,this,&OnlineBookingPage::messageSelectedClient); row->addWidget(msg); row->addStretch(1); l->addLayout(row); m_table=new QTableWidget(this); m_table->setColumnCount(8); m_table->setHorizontalHeaderLabels({QString::fromUtf8("UID"),QString::fromUtf8("Статус"),QString::fromUtf8("Клієнт"),QString::fromUtf8("Телефон"),QString::fromUtf8("Авто"),QString::fromUtf8("Причина"),QString::fromUtf8("Початок"),QString::fromUtf8("Коментар")}); m_table->horizontalHeader()->setSectionResizeMode(QHeaderView::Stretch); m_table->setSelectionBehavior(QAbstractItemView::SelectRows); l->addWidget(m_table); }
QString OnlineBookingPage::selectedAppointmentUid() const{ if(!m_table||!m_table->currentItem()) return {}; return m_table->item(m_table->currentRow(),0)->text(); }
void OnlineBookingPage::refresh(){ QString err; const auto rows=OnlineBookingService::listRecentRequests(300,&err); if(!err.trimmed().isEmpty()) QMessageBox::warning(this,QString::fromUtf8("Помилка"),err); m_table->setRowCount(0); for(const auto& item: rows){ int r=m_table->rowCount(); m_table->insertRow(r); const QStringList values={item.appointmentUid,item.status,item.clientName,item.phone,item.carText,item.serviceReason,item.desiredStartAt,item.comment}; for(int c=0;c<values.size();++c) m_table->setItem(r,c,new QTableWidgetItem(values.at(c))); } }
void OnlineBookingPage::updateSelectedStatus(const QString& status){ const QString uid=selectedAppointmentUid(); if(uid.isEmpty()) return; QString err; if(!OnlineBookingService::updateStatus(uid,status,&err)){ QMessageBox::warning(this,QString::fromUtf8("Помилка"),err); return;} refresh(); emit requestRefreshAll(); }
void OnlineBookingPage::rescheduleSelected(){ const QString uid=selectedAppointmentUid(); if(uid.isEmpty()) return; bool ok=false; const QString start=QInputDialog::getText(this,QString::fromUtf8("Перенести запис"),QString::fromUtf8("Новий час початку ISO, наприклад 2026-05-26T14:00:00"),QLineEdit::Normal,QString(),&ok); if(!ok||start.trimmed().isEmpty()) return; const QString end=QInputDialog::getText(this,QString::fromUtf8("Перенести запис"),QString::fromUtf8("Новий час завершення ISO (можна залишити порожнім)"),QLineEdit::Normal,QString(),&ok); QString err; if(!OnlineBookingService::rescheduleRequest(uid,start,end,&err)){ QMessageBox::warning(this,QString::fromUtf8("Помилка"),err); return;} refresh(); emit requestRefreshAll(); }
void OnlineBookingPage::createOrderFromSelected(){ const QString uid=selectedAppointmentUid(); if(uid.isEmpty()) return; QString orderUid,err; if(!OnlineBookingService::createOrderFromRequest(uid,&orderUid,&err)){ QMessageBox::warning(this,QString::fromUtf8("Помилка"),err); return;} QMessageBox::information(this,QString::fromUtf8("Наряд створено"),QString::fromUtf8("Створено наряд: %1").arg(orderUid)); refresh(); emit requestRefreshAll(); }

void OnlineBookingPage::messageSelectedClient(){ const QString uid=selectedAppointmentUid(); if(uid.isEmpty()) return; bool ok=false; const QString body=QInputDialog::getMultiLineText(this,QString::fromUtf8("Повідомлення клієнту"),QString::fromUtf8("Текст повідомлення"),QString::fromUtf8("Ваш запис підтверджено. Очікуємо вас у погоджений час."),&ok); if(!ok) return; QString err; if(!OnlineBookingService::queueClientMessage(uid,body,&err)){ QMessageBox::warning(this,QString::fromUtf8("Помилка"),err); return;} QMessageBox::information(this,QString::fromUtf8("Готово"),QString::fromUtf8("Повідомлення додано в історію клієнта і синхронізацію.")); refresh(); emit requestRefreshAll(); }
